--
-- Table structure for table `message`
--

DROP TABLE IF EXISTS `message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `message` (
  `MessageId` int(11) NOT NULL AUTO_INCREMENT,
  `SenderId` int(11) DEFAULT NULL,
  `ReceiverId` int(11) DEFAULT NULL,
  `SenderType` varchar(20) DEFAULT 'organization',
  `ReceiverType` varchar(20) DEFAULT 'osa',
  `Subject` varchar(255) DEFAULT NULL,
  `IsRead` tinyint(1) DEFAULT 0,
  `MessageBody` text DEFAULT NULL,
  `MessageDateTime` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`MessageId`),
  KEY `SenderId` (`SenderId`),
  KEY `ReceiverId` (`ReceiverId`),
  CONSTRAINT `message_ibfk_1` FOREIGN KEY (`SenderId`) REFERENCES `user` (`UserId`) ON DELETE CASCADE,
  CONSTRAINT `message_ibfk_2` FOREIGN KEY (`ReceiverId`) REFERENCES `user` (`UserId`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `message`
--

LOCK TABLES `message` WRITE;
/*!40000 ALTER TABLE `message` DISABLE KEYS */;
/*!40000 ALTER TABLE `message` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `org_documents`
--

DROP TABLE IF EXISTS `org_documents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `org_documents` (
  `DocId` int(11) NOT NULL AUTO_INCREMENT,
  `OrgId` int(11) NOT NULL,
  `EventId` int(11) DEFAULT NULL,
  `Title` varchar(255) NOT NULL,
  `DocType` varchar(100) DEFAULT 'Other',
  `Description` text DEFAULT NULL,
  `FilePath` varchar(500) NOT NULL,
  `FileSize` varchar(50) DEFAULT NULL,
  `UploadedAt` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`DocId`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `org_documents`
