INSERT INTO `organization` VALUES (1,'AISERS','The Aviation Institute Students\' Educational Research Society (AISERS) is the premier academic organization of the Institute of Aviation and Aerospace Studies. It fosters research, academic excellence, and intellectual growth among aviation students through seminars, workshops, and collaborative projects.','assets/img/aisers logo.jpg','assets/img/aisers.jpg','aisers_admin','$2y$10$9bYFrb4va1cwHMP7JboD5.JCvC083joBnwtbvrcf0SFsN8xGGxDNO','aisers@naap.edu.ph','Active','Prof. Maria Santos','2019-06-15',NULL,NULL),(2,'AMTSO','The Aircraft Maintenance Technology Student Organization (AMTSO) is dedicated to the professional development of aircraft maintenance technology students. It organizes hands-on training, industry visits, and technical workshops to complement academic learning.','assets/img/amtso logo.jpg','assets/img/amtso.png','amtso_admin','$2y$10$9bYFrb4va1cwHMP7JboD5.JCvC083joBnwtbvrcf0SFsN8xGGxDNO','amtso@naap.edu.ph','Active','Engr. Roberto Cruz','2018-08-20',NULL,NULL),(3,'AEROATSO','The Aerospace and Air Traffic Service Officers (AEROATSO) is an organization for students in the Air Traffic Service program. It aims to develop future air traffic controllers through simulations, drills, and industry exposure programs.','assets/img/aeroatso logo.jpg','assets/img/aeroatso.png','aeroatso_admin','$2y$10$9bYFrb4va1cwHMP7JboD5.JCvC083joBnwtbvrcf0SFsN8xGGxDNO','aeroatso@naap.edu.ph','Active','Capt. Josefino Reyes','2020-03-10',NULL,NULL),(4,'AETSO','The Aviation Electronics Technology Student Organization (AETSO) supports students in aviation electronics technology. It bridges the gap between theoretical knowledge and industry practice through collaborative events and technical scholarships.','assets/img/aetso logo.jpg','assets/img/aetso.jpg','aetso_admin','$2y$10$9bYFrb4va1cwHMP7JboD5.JCvC083joBnwtbvrcf0SFsN8xGGxDNO','aetso@naap.edu.ph','Active','Engr. Liza Dela Cruz','2021-07-05',NULL,NULL),(5,'ELITECH','ELITECH is the Electronics and Information Technology Community Hub, catering to students enrolled in electronics and ICT-related programs. It promotes innovation, digital literacy, and peer mentoring among its members.','assets/img/elitech logo.jpg','assets/img/elitech.png','elitech_admin','$2y$10$9bYFrb4va1cwHMP7JboD5.JCvC083joBnwtbvrcf0SFsN8xGGxDNO','elitech@naap.edu.ph','Active','Mr Richard Niel Peralta, MSIT','2017-09-01',NULL,NULL),(6,'ILAS','The International Language and Arts Society (ILAS) is a cultural and academic organization dedicated to promoting multilingualism, creative arts, and cultural exchange. ILAS provides a platform for students to explore and celebrate diverse cultures.','assets/img/ilas logo.jpg','assets/img/ilas.jpg','ilas_admin','$2y$10$9bYFrb4va1cwHMP7JboD5.JCvC083joBnwtbvrcf0SFsN8xGGxDNO','ilas@naap.edu.ph','Active','Prof. Carla Villanueva','2016-11-15',NULL,NULL);
